export function getEditableAssetInfo(assetId){return EDITABLE_ASSET_INDEX.assets.find(asset=>asset.assetId===assetId)??null;}
export function editableBasePlacement(mapId,source,asset=getEditableAssetInfo(source?.asset)){if(!source)return {editable:false,reason:"대상을 찾지 못했어요."};if(EDITABLE_ASSET_INDEX.baseEligibilityMeta.terrainAssets.includes(source.asset))return {editable:false,reason:asset?.placement?.reason??"연속된 바닥은 지형 도구에서 고쳐 주세요."};if(!asset?.placement?.supported||asset.placement.baked)return {editable:false,reason:"움직이는 배우는 NPC·몬스터 편집에서 고쳐 주세요."};return {editable:true,reason:null};}
